WITH ins AS (INSERT INTO sais_resources (resource_id, family_key, document_number, resource_category, subcategory, jurisdiction_level, jurisdiction, organization_name, organization_type, service_type, official_url, official_contact, statutory_authority, verification_status, last_verified_at, notes, revision) VALUES 
('SAIS-EC-004-04', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_scheme_typology', 'federal', 'federal -- NATIONWIDE', 'Recurring Medicare Fraud Schemes and How They Reach Beneficiaries', 'federal_agency | federal_program', 'medicare_fraud_scheme_typology', 'https://oig.hhs.gov/fraud/consumer-alerts/', 'Senior Medicare Patrol: 877-808-2468 | HHS OIG Hotline: 800-447-8477 | Medicare: 800-633-4227', 'Anti-Kickback Statute (42 U.S.C. sec. 1320a-7b(b)) | Beneficiary Inducement CMP (42 U.S.C. sec. 1320a-7a(a)(5)) | False Claims Act (31 U.S.C. sec. 3729) | Telemarketing Sales Rule (16 CFR Part 310) | Telephone Consumer Protection Act (47 U.S.C. sec. 227)', 'VERIFIED', '2026-08-17', 'TEACH ONE RULE: MEDICARE WILL NOT CALL UNINVITED TO ASK FOR YOUR MEDICARE NUMBER, AND NOTHING LEGITIMATE IS OFFERED FREE BY AN UNSOLICITED CALLER. Every recurring scheme in this pipeline starts with an unsolicited approach, a free offer, and a request for the number. Also warn that unnecessary billed equipment or testing can EXHAUST a benefit the person will genuinely need later -- the harm is not only to Medicare. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 385c756c2003ec0a9f8c60b989d04228e92278834129ebbd07606ef70e75aa1e]', 'v1.0'),
('SAIS-EC-004-05', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_medical_identity_theft', 'federal', 'federal -- NATIONWIDE', 'Medical Identity Theft -- Protecting the Number and the Medical Record', 'federal_agency | credit_reporting_agency', 'medicare_fraud_medical_identity_theft', 'https://www.identitytheft.gov/', 'Medicare: 800-633-4227 | FTC Identity Theft: 877-438-4338 | HHS OIG Hotline: 800-447-8477 | Senior Medicare Patrol: 877-808-2468', 'HIPAA right of access (45 CFR 164.524) | HIPAA right to amend and statement of disagreement (45 CFR 164.526) | Fair Credit Reporting Act (15 U.S.C. sec. 1681; identity theft block at sec. 1681c-2; security freeze at sec. 1681c-1) | Social Security Act Title XVIII (42 U.S.C. sec. 1395 et seq.)', 'VERIFIED', '2026-08-17', 'ASK MEDICARE FOR A NEW MEDICARE NUMBER AND USE THE HIPAA AMENDMENT RIGHT ON EVERY PROVIDER THAT BILLED. A reissued number stops future misuse and is not offered unless requested. And when a provider refuses to remove a fraudulent entry, file a STATEMENT OF DISAGREEMENT -- it must accompany any future disclosure, which means the next clinician treating the beneficiary sees the dispute rather than acting on a false diagnosis. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0cd862998a07f1419f7d86607c6800528acd0b3747b52ffe7a9cc9e9c68754c6]', 'v1.0'),
('SAIS-EC-004-06', 'systemic_abuse_intelligence', 304, 'medicare_fraud', 'medicare_fraud_prevention_and_marketing', 'federal + state', 'federal + state -- ALL_STATES', 'Prevention -- Marketing Rules, Enrollment Abuse, and Guarding the Number', 'federal_agency | state_regulator', 'medicare_fraud_prevention_and_marketing', 'https://www.medicare.gov/plan-compare/', 'Medicare: 800-633-4227 | Your state SHIP for unbiased plan counseling | Your state Department of Insurance | Senior Medicare Patrol: 877-808-2468', 'Medicare Advantage and Part D marketing requirements (42 CFR Part 422 Subpart V; 42 CFR Part 423 Subpart V) | Beneficiary inducement prohibition (42 U.S.C. sec. 1320a-7a(a)(5)) | Special enrollment periods (42 CFR 422.62; 423.38) | Telephone Consumer Protection Act (47 U.S.C. sec. 227) | State insurance agent licensing statutes.', 'VERIFIED', '2026-08-17', 'AN ENROLLMENT MADE WITHOUT KNOWING CONSENT CAN GENERALLY BE UNDONE -- call 800-633-4227 and ask about retroactive disenrollment and a special enrollment period, then report the agent to the STATE DEPARTMENT OF INSURANCE, which licenses them. And get plan advice from SHIP rather than from anyone selling: free, unbiased, no commission, reachable at 800-677-1116. [address_resolution: Resolve via the agency''s FIELD or REGIONAL office locator; input = state or ZIP. Use the regional office, not national headquarters, for individual matters.] [doc_code: EC-004 | pipeline: Medicare Fraud] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: b2cad2ae841b77eb0a3f70bcc0a751c6b7ae0568e90dcc7747ca96b11fa87350]', 'v1.0'),
('SAIS-EC-005-01', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_facility_type_identification', 'state', 'state -- ALL_STATES', 'Identify the Facility''s License Type Before Anything Else', 'state_licensing_agency', 'assisted_living_facility_type_identification', 'https://eldercare.acl.gov/', 'Eldercare Locator: 800-677-1116 | Your state residential care licensing office -- ask the aging agency in the table below', 'State residential care, assisted living, and adult family home licensing acts | State public records acts | Older Americans Act (42 U.S.C. sec. 3001 et seq.)', 'VERIFIED', '2026-08-17', 'PULL THE FACILITY''S PUBLIC LICENSE AND INSPECTION RECORD BEFORE YOU FILE ANYTHING. It takes minutes, it is free, and it tells you the license type (which determines which rules apply), the correct regulator, and whether this operator has a substantiated history of the exact conduct you are reporting. Do NOT assume federal nursing home rules apply -- for assisted living and adult family homes they generally do not, and citing the wrong law weakens an otherwise strong complaint. [address_resolution: Resolve via the state licensing agency''s regional office directory; input = facility county. The public license registry lists the regional office assigned to each licensed facility.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f9a2ba5bee1116d776de2815ede0f37c9f97ac86b3bb1f8c02cdf5b20f58bbc7]', 'v1.0'),
('SAIS-EC-005-02', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_licensing_complaint', 'state', 'state -- ALL_STATES', 'State Licensing Complaint -- The Only Route With Authority Over the License', 'state_licensing_agency', 'assisted_living_licensing_complaint', 'https://eldercare.acl.gov/Public/Index.aspx', 'Your state residential care/assisted living licensing office | Eldercare Locator will route you: 800-677-1116', 'State residential care and assisted living licensing acts and regulations | State administrative procedure acts | Anti-retaliation provisions in state long-term care statutes | Elder Justice Act (42 U.S.C. sec. 1397j et seq.)', 'VERIFIED', '2026-08-17', 'CITE THE SPECIFIC LICENSE REGULATION AND STATE WHETHER THERE IS IMMEDIATE DANGER. Those two elements determine whether your complaint is investigated on-site in 48 hours or screened into a queue. Ask for the completed investigation report afterward regardless of outcome -- a closure letter is not the report, and the report frequently documents findings the letter does not mention. [address_resolution: Resolve via the state licensing agency''s regional office directory; input = facility county. The public license registry lists the regional office assigned to each licensed facility.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 1c2f34aec50049506bf119e4667418eb870a37523dbfba9ef6a40cf673596993]', 'v1.0'),
('SAIS-EC-005-03', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_ombudsman', 'federal + state', 'federal + state -- ALL_STATES', 'Long-Term Care Ombudsman -- Advocacy That Works Inside the Facility', 'federal_program | state_program', 'assisted_living_ombudsman', 'https://theconsumervoice.org/get_help', 'National LTC Ombudsman locator via Eldercare Locator: 800-677-1116 | Your state LTC Ombudsman -- see jurisdiction table', 'Older Americans Act -- LTC Ombudsman Program (42 U.S.C. sec. 3058g) | State Ombudsman authorizing statutes | 45 CFR Part 1324 (Ombudsman program rule, including resident-directed and confidentiality requirements)', 'VERIFIED', '2026-08-17', 'CALL 800-677-1116 AND ASK FOR THE LOCAL LONG-TERM CARE OMBUDSMAN FOR THIS FACILITY. It is free, independent, available regardless of how care is paid for, and it is the fastest route to changing what happens to the resident tomorrow. File the licensing complaint in parallel -- the Ombudsman changes conditions, the licensing agency creates the enforcement record, and neither substitutes for the other. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: b2f13ec8dc06c587c998ab7f9e945156c2ebf7fb11aebe9633ff97f26b87ea18]', 'v1.0'),
('SAIS-EC-005-04', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_aps_report', 'state', 'state -- ALL_STATES', 'Adult Protective Services -- Any Person Can Report, in Every State', 'state_agency', 'assisted_living_aps_report', 'https://eldercare.acl.gov/Public/Index.aspx', 'Eldercare Locator (routes to your state APS): 800-677-1116 | National Adult Maltreatment reporting via your state APS -- see jurisdiction table | 911 for immediate danger', 'Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Older Americans Act (42 U.S.C. sec. 3001 et seq.) | State adult protective services acts and mandatory reporting statutes | State vulnerable adult abuse statutes.', 'VERIFIED', '2026-08-17', 'FILE WITH APS AND LICENSING BOTH. They investigate different things -- APS investigates harm to the person, licensing investigates the facility -- and neither reliably forwards to the other. Anyone may report, reports may be anonymous, and good faith reporters have immunity in every state. Ask for the report number at intake. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 47bc1a41d8ea89f42f227bdd7be79c49bc2d9d1de52d9ac5caaf78072e008610]', 'v1.0'),
('SAIS-EC-005-05', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_involuntary_discharge', 'state', 'state -- ALL_STATES', 'Involuntary Discharge or Transfer -- Notice, Grounds, and the Hearing Clock', 'state_licensing_agency | state_court', 'assisted_living_involuntary_discharge', 'https://theconsumervoice.org/get_help', 'Your state LTC Ombudsman (immediately): 800-677-1116 | Your state residential care licensing office | Local legal aid -- dial 211', 'State residential care and assisted living discharge/transfer statutes and regulations | State landlord-tenant law where it applies to residential care | Anti-retaliation provisions in state long-term care statutes | Fair Housing Act reasonable accommodation (42 U.S.C. sec. 3604(f))', 'VERIFIED', '2026-08-17', 'REQUEST THE HEARING BEFORE THE EFFECTIVE DATE AND DO NOT MOVE VOLUNTARILY FIRST. Moving out generally ends the challenge. Call the Ombudsman the day the notice arrives and get your state''s exact hearing deadline -- it can be as short as ten days. Separately: if increased care needs are the stated reason, a reasonable accommodation request under fair housing law is available in many settings and is almost never raised. [address_resolution: Resolve via the state licensing agency''s regional office directory; input = facility county. The public license registry lists the regional office assigned to each licensed facility.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 69a1145fbeed3cacc7fd2cd742f35bc6127ffdaa36d494321ee13df802951643]', 'v1.0'),
('SAIS-EC-005-06', 'systemic_abuse_intelligence', 305, 'assisted_living_complaint', 'assisted_living_records_and_civil_claim', 'state', 'state -- ALL_STATES', 'Records, the Admission Agreement, and Preserving a Civil Claim', 'state_court | legal_aid', 'assisted_living_records_and_civil_claim', 'https://www.lawhelp.org/', 'Your state bar lawyer referral service | Dial 211 for local legal aid and elder law referrals | HHS Office for Civil Rights (health records): 800-368-1019', 'State residential care licensing and records access statutes | HIPAA right of access (45 CFR 164.524) | 42 CFR 483.70(n) (arbitration agreements in federally certified LTC facilities) | State restrictions on third-party guaranties and admission agreement terms | State wrongful death statutes.', 'VERIFIED', '2026-08-17', 'SEND THE PRESERVATION LETTER AND REQUEST THE NEGOTIATED SERVICE AGREEMENT TODAY. The service agreement defines what the facility promised, which is what converts ''they neglected her'' into a documented failure to deliver contracted care. Then read the admission agreement for an arbitration clause and for any third-party payment guaranty -- families routinely discover both only after a dispute begins, and in many states a required personal guaranty was never enforceable to begin with. [address_resolution: Resolve via the state court locator for the county of filing; input = county + case type. Ask the clerk for the SELF-HELP CENTER window, which is frequently a different address from the main clerk''s office.] [doc_code: EC-005 | pipeline: Assisted Living Complaint] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 64fc0e95b4dfc32cf7d151efb7b6dec723a8a392039cd39fec68b46df51c054f]', 'v1.0'),
('SAIS-EC-006-01', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_setting_identification', 'state', 'state -- ALL_STATES', 'Identify the Care Setting Before Choosing the Route', 'state_agency', 'elder_neglect_setting_identification', 'https://eldercare.acl.gov/', 'Eldercare Locator: 800-677-1116 | Adult Protective Services via the same number | Your Area Agency on Aging', 'Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Older Americans Act (42 U.S.C. sec. 3001 et seq.) | State adult protective services acts | State home care agency licensing statutes | Medicare home health conditions of participation (42 CFR Part 484)', 'VERIFIED', '2026-08-17', 'CALL 800-677-1116 AND STATE THE SETTING. The Eldercare Locator routes to APS, the Area Agency on Aging, and the Ombudsman as appropriate, and the setting determines everything downstream. Where an unpaid family caregiver is failing, treat capacity as the first hypothesis -- respite and in-home services frequently resolve what a report alone will not. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 6d6aeb3e53df944693f99c62abd03368faa06872a3f9e91c8b3ed510d166440e]', 'v1.0'),
('SAIS-EC-006-02', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_aps_report', 'state', 'state -- ALL_STATES', 'Adult Protective Services -- What to Report and How to Get It Investigated', 'state_agency', 'elder_neglect_aps_report', 'https://eldercare.acl.gov/Public/Index.aspx', 'Adult Protective Services via Eldercare Locator: 800-677-1116 | 911 for immediate danger | Your state APS -- see jurisdiction table', 'Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Older Americans Act (42 U.S.C. sec. 3001 et seq.) | State adult protective services acts | State vulnerable adult neglect statutes | State mandatory reporter statutes.', 'VERIFIED', '2026-08-17', 'REPORT CONCRETE OBSERVATIONS WITH DATES, NOT CONCLUSIONS. ''She is being neglected'' is screened out; ''she has lost roughly twenty pounds since June, there was no food in the house on these three dates, and her pressure sore has not been seen by a clinician'' is investigated. Note that a competent adult may refuse services -- if that happens, the route shifts to capacity assessment and the Self-Neglect pipeline rather than enforcement. [address_resolution: Resolve via the state agency''s LOCAL OFFICE locator; input = ZIP or county. Most state agencies operate county or district offices rather than a single statewide address.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ed941e3b5e4af58fa82be2e6850a800c00c4fc881534cd58175fe6dc209c1c6e]', 'v1.0'),
('SAIS-EC-006-03', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_medical_documentation', 'federal + state', 'federal + state -- ALL_STATES', 'Medical Documentation -- The Clinical Record That Makes a Neglect Case', 'healthcare_provider | federal_agency', 'elder_neglect_medical_documentation', 'https://www.hhs.gov/hipaa/for-individuals/medical-records/index.html', 'HHS Office for Civil Rights (records access): 800-368-1019 | The older adult''s primary care provider | Local emergency department', 'HIPAA right of access (45 CFR 164.524) | State mandatory reporter statutes | Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | Emergency Medical Treatment and Labor Act (42 U.S.C. sec. 1395dd)', 'VERIFIED', '2026-08-17', 'GET A MEDICAL EVALUATION AND REQUEST PRIOR-YEAR RECORDS IN THE SAME BREATH. The trajectory across visits -- weight, labs, skin, function -- is what converts a family''s worry into documented decline under someone''s care. Ask the clinician to document whether the findings are CONSISTENT with the explanation given; that sentence in a chart carries more weight than any affidavit. [address_resolution: Resolve via HRSA findahealthcenter.hrsa.gov for sliding-scale sites; input = ZIP. For a specific provider, use the state licensing registry.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 0d9e922d9a1f52ecde764ff66fe8556f2e73e38af8442bb6b29186bdeb8e0eb1]', 'v1.0'),
('SAIS-EC-006-04', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_home_care_agency_complaint', 'federal + state', 'federal + state -- ALL_STATES', 'Paid In-Home Care -- Agency Licensing, Federal Conditions, and the Service Plan', 'state_licensing_agency | federal_agency', 'elder_neglect_home_care_agency_complaint', 'https://www.medicare.gov/care-compare/', 'Your state home care licensing office -- ask the aging agency in the jurisdiction table | Medicare: 800-633-4227 | State survey agency', 'Medicare home health Conditions of Participation (42 CFR Part 484) | Patient rights (42 CFR 484.50) | Electronic visit verification requirement (42 U.S.C. sec. 1396b(l)) | State home care agency licensing statutes | Medicaid Fraud Control Units (42 U.S.C. sec. 1396b(q))', 'VERIFIED', '2026-08-17', 'REQUEST THE SERVICE PLAN AND THE ELECTRONIC VISIT VERIFICATION RECORDS. The service plan states what was promised; the EVV data shows whether the visits actually happened and how long they lasted. Missed visits billed as delivered convert a care complaint into a fraud referral to the Medicaid Fraud Control Unit, which carries criminal authority the licensing route does not. [address_resolution: Resolve via the state licensing agency''s regional office directory; input = facility county. The public license registry lists the regional office assigned to each licensed facility.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4e088e11e2ea7fed24e6b2e11f66c6e03afda675b76aff46b1fe5179110a5416]', 'v1.0'),
('SAIS-EC-006-05', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_caregiver_support_services', 'federal + state', 'federal + state -- ALL_STATES', 'Caregiver Capacity -- The Services That Prevent Neglect From Recurring', 'federal_program | state_agency', 'elder_neglect_caregiver_support_services', 'https://acl.gov/programs/support-caregivers', 'Eldercare Locator / Area Agency on Aging: 800-677-1116 | Your state Medicaid agency | Dial 211', 'Older Americans Act -- National Family Caregiver Support Program (42 U.S.C. sec. 3030s) | Older Americans Act Title III supportive and nutrition services (42 U.S.C. sec. 3030d) | Medicaid Home and Community-Based Services (42 U.S.C. sec. 1396n(c) and (i)) | Olmstead v. L.C., 527 U.S. 581.', 'VERIFIED', '2026-08-17', 'ASK FOR RESPITE CARE AND FOR MEDICAID HCBS BY NAME, AND ASK WHETHER A FAMILY MEMBER CAN BE PAID AS THE CAREGIVER. Most states permit consumer-directed care that pays a relative, and almost nobody is told. Where neglect is a capacity failure rather than intent, these services are the actual remedy -- and getting on any waiver waiting list today matters, because position is dated from application, not from need. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 2cac296a08961b50af4ae30bf6679195c1fbcc3a59c17168687e617a5d11f5ca]', 'v1.0'),
('SAIS-EC-006-06', 'systemic_abuse_intelligence', 306, 'elder_neglect', 'elder_neglect_civil_criminal_referral', 'state', 'state -- ALL_STATES', 'Civil and Criminal Accountability for Neglect', 'law_enforcement | state_court | state_attorney_general', 'elder_neglect_civil_criminal_referral', 'https://www.lawhelp.org/', '911 or your local law enforcement | Your state Attorney General''s Medicaid Fraud Control Unit | Your state bar lawyer referral service | Dial 211 for legal aid', 'State vulnerable adult neglect and endangerment statutes | State enhanced elder abuse civil remedy statutes | Medicaid Fraud Control Units (42 U.S.C. sec. 1396b(q)) | Elder Justice Act (42 U.S.C. sec. 1397j et seq.) | State wrongful death and survival statutes | State tort claims acts.', 'VERIFIED', '2026-08-17', 'ASK WHETHER YOUR STATE HAS AN ENHANCED ELDER ABUSE CIVIL REMEDY WITH FEE-SHIFTING. Many do, and it is frequently what makes an otherwise uneconomic case one an attorney will take on contingency. Then determine on day one whether any potential defendant is a government entity -- the notice-of-claim deadline can be 30 days and it is the most common way a valid neglect claim is permanently lost. [address_resolution: Resolve via the agency of jurisdiction for the location of the incident; input = incident address. For federal matters use the FBI field office locator; input = state.] [doc_code: EC-006 | pipeline: Elder Neglect] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 117c0d57e8704d01abe019952567abee5bf1ffedcbf70eaf41f34aca1d4bdfa7]', 'v1.0'),
('SAIS-EC-007-01', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_policy_triggers', 'state', 'state -- ALL_STATES', 'Read the Policy First -- Benefit Triggers Are the Whole Fight', 'insurance_carrier | state_regulator', 'ltc_insurance_policy_triggers', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table | Your state SHIP for free counseling | NAIC consumer portal', 'State insurance codes governing long-term care insurance (based on the NAIC Long-Term Care Insurance Model Act and Model Regulation) | Tax-qualified LTC policy standards (26 U.S.C. sec. 7702B) | McCarran-Ferguson Act (15 U.S.C. sec. 1011) | State unfair claims settlement practices acts.', 'VERIFIED', '2026-08-17', 'CHECK WHETHER THE DENIAL ADDRESSED THE COGNITIVE TRIGGER AT ALL. It is independent of the ADL trigger, and a person with dementia who can still physically bathe and dress may qualify on cognition alone. Then check whether the elimination period counts CALENDAR days or SERVICE days -- that single word changes a three-month wait into a seven-month one and is the most common source of surprise in this pipeline. [address_resolution: Resolve via the carrier''s claims correspondence address on the policy declarations page. Regulator complaints go to the state Department of Insurance instead.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 4968cf521f092a2df2ee2880286b5b39678bdec1512abdc92213073eef958aa4]', 'v1.0'),
('SAIS-EC-007-02', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_claim_file_and_assessment', 'state', 'state -- ALL_STATES', 'The Claim File and the Functional Assessment', 'insurance_carrier | healthcare_provider', 'ltc_insurance_claim_file_and_assessment', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table | The insured''s treating clinician | HHS Office for Civil Rights (records): 800-368-1019', 'State long-term care insurance regulations (NAIC model-based) | State unfair claims settlement practices acts | 26 U.S.C. sec. 7702B (tax-qualified policy standards) | HIPAA right of access (45 CFR 164.524) | ERISA (29 U.S.C. sec. 1001) where employer-sponsored.', 'VERIFIED', '2026-08-17', 'GET THE ASSESSMENT REPORT AND ATTACK ITS METHOD. A twenty-minute phone call used to find a person with dementia independent is the single most common defect in this pipeline, and it is visible on the face of the report. Pair the challenge with a two-to-four-week CAREGIVER LOG -- day-by-day records of what help was actually needed beat a snapshot assessment more reliably than any argument. [address_resolution: Resolve via the carrier''s claims correspondence address on the policy declarations page. Regulator complaints go to the state Department of Insurance instead.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 00df29a77b79eeab768a5854daf416cfbd2a287bc6ad64de421e258e36db4d27]', 'v1.0'),
('SAIS-EC-007-03', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_lapse_and_reinstatement', 'state', 'state -- ALL_STATES', 'Lapse for Nonpayment -- The Protections That Frequently Void a Lapse', 'insurance_carrier | state_regulator', 'ltc_insurance_lapse_and_reinstatement', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table | Your state SHIP for free counseling', 'State long-term care insurance regulations based on the NAIC Long-Term Care Insurance Model Regulation -- unintentional lapse, third-party notice, and reinstatement for cognitive impairment | Nonforfeiture and contingent benefit upon lapse provisions | 26 U.S.C. sec. 7702B.', 'VERIFIED', '2026-08-17', 'IF A POLICY LAPSED, ASK TWO QUESTIONS IN WRITING BEFORE ACCEPTING IT: was the third-party notice option offered and was notice actually sent, and does the state''s COGNITIVE IMPAIRMENT REINSTATEMENT right apply. Both are required in most states, both are rarely volunteered, and either one can restore a policy that everyone assumed was gone. Before letting any policy lapse over a rate increase, ask about the CONTINGENT BENEFIT UPON LAPSE -- reduced paid-up coverage beats nothing. [address_resolution: Resolve via the carrier''s claims correspondence address on the policy declarations page. Regulator complaints go to the state Department of Insurance instead.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: ab2dc292a03fc450fc40089608036a14f680247c28946b4aa91fe890fdb2a24a]', 'v1.0'),
('SAIS-EC-007-04', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_rescission_and_misrepresentation', 'state', 'state -- ALL_STATES', 'Rescission for Application Misstatements -- Incontestability and Post-Claim Underwriting', 'insurance_carrier | state_regulator', 'ltc_insurance_rescission_and_misrepresentation', 'https://content.naic.org/consumer.htm', 'Your state Department of Insurance -- see jurisdiction table | Your state SHIP for free counseling', 'State long-term care insurance regulations based on the NAIC Long-Term Care Insurance Model Regulation -- incontestability tiers and prohibition on post-claim underwriting | State insurance code misrepresentation provisions | 26 U.S.C. sec. 7702B.', 'VERIFIED', '2026-08-17', 'IF THE POLICY IS MORE THAN TWO YEARS OLD, LEAD THE APPEAL WITH THAT FACT. After two years most states permit rescission only for a KNOWINGLY false and material misstatement about the specific condition claimed -- a bar insurers frequently cannot meet. And if the insurer did no real underwriting at issuance and is reviewing the medical history for the first time now, name it as POST-CLAIM UNDERWRITING in a Department of Insurance complaint; that is a regulatory violation independent of the contract. [address_resolution: Resolve via the carrier''s claims correspondence address on the policy declarations page. Regulator complaints go to the state Department of Insurance instead.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: f2760faec5f4f9ede5863a568978aced5b56d16a41536677e573a4a52fea2edf]', 'v1.0'),
('SAIS-EC-007-05', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_regulator_and_ship', 'federal + state', 'federal + state -- ALL_STATES', 'The Department of Insurance Complaint and Free SHIP Counseling', 'state_regulator | federal_program', 'ltc_insurance_regulator_and_ship', 'https://www.shiphelp.org/', 'Your state Department of Insurance -- see jurisdiction table | Your state SHIP (free Medicare and LTC counseling) | Eldercare Locator: 800-677-1116', 'State unfair claims settlement practices acts (NAIC model-based) | State long-term care insurance regulations | State Health Insurance Assistance Program (42 U.S.C. sec. 1395b-4) | Long-Term Care Partnership programs (42 U.S.C. sec. 1396p(b)(1)(C)) | McCarran-Ferguson Act (15 U.S.C. sec. 1011)', 'VERIFIED', '2026-08-17', 'FILE THE DEPARTMENT OF INSURANCE COMPLAINT AT THE SAME TIME AS THE APPEAL, NOT AFTER IT, AND CALL YOUR SHIP AT 800-677-1116 FIRST. SHIP counselors read policies for free with no sales incentive, which is the exact help families in this pipeline cannot otherwise get. And if the policy was a PARTNERSHIP policy, ask about Medicaid asset protection -- assets equal to benefits paid can be protected later, and almost no one is told. [address_resolution: Resolve via the state Department of Insurance office directory; input = state. Larger states operate consumer service offices in multiple cities.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: dc17e611bfe3284f630f7729bab2fe8d8c0e47ed0b6db437172b35f4aa6743e4]', 'v1.0'),
('SAIS-EC-007-06', 'systemic_abuse_intelligence', 307, 'long_term_care_insurance', 'ltc_insurance_fallback_coverage', 'federal + state', 'federal + state -- ALL_STATES', 'When Coverage Fails -- Medicaid, Veterans Benefits, and Community Alternatives', 'federal_program | state_agency', 'ltc_insurance_fallback_coverage', 'https://acl.gov/programs', 'Eldercare Locator / Area Agency on Aging: 800-677-1116 | Your state Medicaid agency | VA: 800-827-1000 | Dial 211', 'Medicaid long-term services and supports (42 U.S.C. sec. 1396a, 1396n(c), (i), (k)) | Spousal impoverishment (42 U.S.C. sec. 1396r-5) | Medicaid fair hearing and continuation (42 CFR 431.230) | VA Aid and Attendance pension (38 U.S.C. sec. 1521; 38 CFR 3.351-3.352) | PACE (42 U.S.C. sec. 1395eee, 1396u-4) | Older Americans Act (42 U.S.C. sec. 3001 et seq.)', 'VERIFIED', '2026-08-17', 'APPLY FOR MEDICAID AND GET ON THE HCBS WAITING LIST WHILE THE INSURANCE APPEAL IS STILL PENDING. These run on separate tracks and waiting list position is dated from application. Ask about VA AID AND ATTENDANCE if there is any veteran in the family, including a surviving spouse -- it is one of the most underclaimed benefits in this entire category. And ask whether your state''s HCBS program will pay a family member to provide the care; most will. [address_resolution: Resolve via the program''s grantee or local-provider locator; input = ZIP or county. Federal programs deliver through local grantees with their own addresses.] [doc_code: EC-007 | pipeline: Long-Term Care Insurance] [src: luminari-SAIS-ALL-RECORDS-2026.csv | sha8:fb433b18] [record_sha256: 666c5355ee5c3cb2449eaaa719ed83aed0a0fc7408ab6f219c4b1d2715173d5d]', 'v1.0')
